const MUSE_USER_AGENT: &str = "muse-code/1.0.2";

pub struct MuseProvider {
    client: reqwest::Client,
    base_url: String,
    access_token: String,
}

impl MuseProvider {
    pub fn new(access_token: impl Into<String>, base_url: Option<&str>) -> Self {
        Self {
            client: reqwest::Client::new(),
            base_url: base_url.unwrap_or("https://api.muse.ai/v1").to_string(),
            access_token: access_token.into(),
        }
    }

    /// Rewrites raw SSE JSON, normalizing chunks that lack choices or send null choices to empty array
    pub fn sanitize_sse_payload(payload: &str) -> String {
        if let Ok(mut val) = serde_json::from_str::<serde_json::Value>(payload) {
            if let Some(obj) = val.as_object_mut() {
                if !obj.contains_key("choices") || obj.get("choices").map(|c| c.is_null()).unwrap_or(false) {
                    obj.insert("choices".to_string(), json!([]));
                    return serde_json::to_string(&val).unwrap_or_else(|_| payload.to_string());
                }
            }
        }
        payload.to_string()
    }
}

#[async_trait]
impl ModelProvider for MuseProvider {
    fn provider_name(&self) -> &str {
        "muse"
    }

    async fn stream_chat(
        &self,
        request: ChatRequest,
        event_sender: Sender<StreamEvent>,
        cancellation: CancellationToken,
    ) -> Result<()> {
        let endpoint = format!("{}/chat/completions", self.base_url.trim_end_matches('/'));

        let mut headers = HeaderMap::new();
        headers.insert(CONTENT_TYPE, HeaderValue::from_static("application/json"));
        headers.insert(
            AUTHORIZATION,
            HeaderValue::from_str(&format!("Bearer {}", self.access_token))
                .map_err(|e| OdonError::Auth(e.to_string()))?,
        );
        headers.insert(USER_AGENT, HeaderValue::from_static(MUSE_USER_AGENT));

        let mut messages_payload = Vec::new();
        for msg in request.messages {
            let role_str = match msg.role {
                MessageRole::User => "user",
                MessageRole::Assistant => "assistant",
                MessageRole::System => "system",
                MessageRole::Tool => "tool",
            };
            messages_payload.push(json!({
                "role": role_str,
                "content": msg.content.text,
            }));
        }

        let body = json!({
            "model": request.model,
            "messages": messages_payload,
            "stream": true,
        });

        let resp = self
            .client
            .post(&endpoint)
            .headers(headers)
            .json(&body)
            .send()
            .await
            .map_err(|e| OdonError::Provider {
                provider: "muse".to_string(),
                message: format!("Muse HTTP request failed: {}", e),
            })?;

        if !resp.status().is_success() {
            let err_body = resp.text().await.unwrap_or_default();
            return Err(OdonError::Provider {
                provider: "muse".to_string(),
                message: format!("Muse HTTP status error: {}", err_body),
            });
        }

        let mut stream = resp.bytes_stream().eventsource();

        loop {
            tokio::select! {
                _ = cancellation.cancelled() => {
                    let _ = event_sender.send(StreamEvent::Done).await;
                    return Ok(());
                }
                item = stream.next() => {
                    match item {
                        Some(Ok(event)) => {
                            if event.data == "[DONE]" {
                                let _ = event_sender.send(StreamEvent::Done).await;
                                break;
                            }
                            let sanitized = Self::sanitize_sse_payload(&event.data);
                            if let Ok(val) = serde_json::from_str::<serde_json::Value>(&sanitized) {
                                if let Some(choices) = val.get("choices").and_then(|c| c.as_array()) {
                                    if let Some(first) = choices.first() {
                                        if let Some(delta) = first.get("delta").and_then(|d| d.get("content")).and_then(|c| c.as_str()) {
                                            let _ = event_sender.send(StreamEvent::TextDelta(delta.to_string())).await;
                                        }
                                    }
                                }
                            }
                        }
                        Some(Err(e)) => {
                            let _ = event_sender.send(StreamEvent::Error(format!("Muse SSE error: {}", e))).await;
                            break;
                        }
                        None => {
                            let _ = event_sender.send(StreamEvent::Done).await;
                            break;
                        }
                    }
                }
            }
        }

        Ok(())
    }
}

use base64::engine::general_purpose::URL_SAFE_NO_PAD;
use base64::Engine;
use chrono::{DateTime, Utc};
use odon_core::{OdonError, Result};
use ring::rand::{SecureRandom, SystemRandom};
use serde::{Deserialize, Serialize};
use sha2::{Digest, Sha256};
use std::net::SocketAddr;
use tokio::io::{AsyncReadExt, AsyncWriteExt};
use tokio::net::TcpListener;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct OAuthToken {
    pub provider: String,
    pub access_token: String,
    pub refresh_token: Option<String>,
    pub expires_at: Option<DateTime<Utc>>,
    pub account_id: Option<String>,
}

pub struct OAuthHandler;

impl OAuthHandler {
    pub fn generate_pkce() -> Result<(String, String)> {
        let mut buf = [0u8; 32];
        SystemRandom::new()
            .fill(&mut buf)
            .map_err(|_| OdonError::Auth("Failed to generate secure random bytes".to_string()))?;

        let verifier = URL_SAFE_NO_PAD.encode(buf);
        let hash = Sha256::digest(verifier.as_bytes());
        let challenge = URL_SAFE_NO_PAD.encode(hash);

        Ok((verifier, challenge))
    }

    /// Spawns an ephemeral TCP listener on 127.0.0.1 to capture the redirect code
    pub async fn wait_for_redirect_code(port: u16) -> Result<String> {
        let addr: SocketAddr = format!("127.0.0.1:{}", port)
            .parse()
            .map_err(|e| OdonError::Auth(format!("Invalid address: {}", e)))?;

        let listener = TcpListener::bind(addr)
            .await
            .map_err(|e| OdonError::Auth(format!("Failed to bind loopback OAuth port: {}", e)))?;

        let (mut socket, _) = listener
            .accept()
            .await
            .map_err(|e| OdonError::Auth(format!("Failed to accept connection: {}", e)))?;

        let mut buf = [0u8; 2048];
        let n = socket
            .read(&mut buf)
            .await
            .map_err(|e| OdonError::Auth(format!("Failed to read HTTP request: {}", e)))?;

        let req = String::from_utf8_lossy(&buf[..n]);
        let first_line = req.lines().next().unwrap_or_default();

        // Extract code from "GET /?code=... HTTP/1.1" or "GET /callback?code=..."
        let mut auth_code = None;
        if let Some(path) = first_line.split_whitespace().nth(1) {
            if let Some(query) = path.split('?').nth(1) {
                for pair in query.split('&') {
                    let mut parts = pair.split('=');
                    if let (Some(k), Some(v)) = (parts.next(), parts.next()) {
                        if k == "code" {
                            auth_code = Some(v.to_string());
                            break;
                        }
                    }
                }
            }
        }

        // Return a clean HTML success response
        let resp_body = "<!DOCTYPE html><html><body style='font-family: sans-serif; text-align: center; padding: 50px;'><h2>ODON OAuth Successful!</h2><p>You can close this tab and return to ODON.</p></body></html>";
        let response = format!(
            "HTTP/1.1 200 OK\r\nContent-Type: text/html\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
            resp_body.len(),
            resp_body
        );

        let _ = socket.write_all(response.as_bytes()).await;

        auth_code.ok_or_else(|| OdonError::Auth("No authorization code found in redirect".to_string()))
    }
}

use async_trait::async_trait;
