impl ApprovalEngine {
    pub fn new(policy: SecurityPolicy) -> Self {
        Self {
            policy: Arc::new(RwLock::new(policy)),
            pending: Arc::new(RwLock::new(HashMap::new())),
        }
    }

    pub async fn check_risk(&self, tool_name: &str) -> RiskTier {
        match tool_name {
            "fs_read" | "fs_list" | "fs_search" | "git_status" | "git_diff" | "git_log" | "github_list_issues" | "github_get_repo" | "mcp_list_tools" | "web_search" | "web_fetch" | "system_info" | "calc_eval" | "memory_recall" => {
                RiskTier::Tier0ReadOnly
            }
            "fs_write" | "fs_edit" | "git_commit" | "git_branch" | "artifact_create_code" | "artifact_create_document" | "artifact_create_image" | "github_create_issue" | "memory_store" => {
                RiskTier::Tier1WorkspaceMutating
            }
            _ => RiskTier::Tier2SystemMutating, // shell_exec, fs_delete, git_push, destructive actions
        }
    }

    pub async fn evaluate_and_request(
        &self,
        session_id: &str,
        tool_name: &str,
        parameters: &serde_json::Value,
        description: &str,
    ) -> Result<ApprovalDecision, String> {
        let risk = self.check_risk(tool_name).await;
        let policy = self.policy.read().await;

        // In locked mode, all mutating calls rejected
        if policy.mode == ExecutionMode::Locked && risk > RiskTier::Tier0ReadOnly {
            return Ok(ApprovalDecision::Rejected {
                reason: "Workspace is in Locked mode: all mutating actions are refused".to_string(),
            });
        }

        // Auto approve Tier 0 read-only
        if risk == RiskTier::Tier0ReadOnly {
            return Ok(ApprovalDecision::Approved);
        }

        // Autonomous mode auto-approves Tier 1
        if policy.mode == ExecutionMode::Autonomous && risk == RiskTier::Tier1WorkspaceMutating {
            return Ok(ApprovalDecision::Approved);
        }

        // Otherwise requires interactive approval (Tier 2 in Autonomous, or Tier 1 & 2 in Supervised)
        let id = Uuid::new_v4().to_string();
        let (tx, rx) = oneshot::channel();

        let req = ApprovalRequest {
            id: id.clone(),
            session_id: session_id.to_string(),
            tool_name: tool_name.to_string(),
            risk_tier: risk,
            description: description.to_string(),
            parameters: parameters.clone(),
            created_at: Utc::now(),
        };

        {
            let mut pending = self.pending.write().await;
            pending.insert(id.clone(), PendingRequest { request: req, sender: tx });
        }

        // Wait for decision or timeout
        match tokio::time::timeout(std::time::Duration::from_secs(300), rx).await {
            Ok(Ok(decision)) => Ok(decision),
            Ok(Err(_)) => Ok(ApprovalDecision::Rejected {
                reason: "Approval channel closed".to_string(),
            }),
            Err(_) => {
                let mut pending = self.pending.write().await;
                pending.remove(&id);
                Ok(ApprovalDecision::Expired)
            }
        }
    }

    pub async fn submit_decision(&self, approval_id: &str, decision: ApprovalDecision) -> bool {
        let mut pending = self.pending.write().await;
        if let Some(entry) = pending.remove(approval_id) {
            let _ = entry.sender.send(decision);
            true
        } else {
            false
        }
    }

    pub async fn list_pending(&self) -> Vec<ApprovalRequest> {
        let pending = self.pending.read().await;
        pending.values().map(|p| p.request.clone()).collect()
    }

    pub async fn get_policy(&self) -> SecurityPolicy {
        self.policy.read().await.clone()
    }

    pub async fn update_mode(&self, mode: ExecutionMode) {
        let mut policy = self.policy.write().await;
        policy.mode = mode;
    }
}

use chrono::{DateTime, Utc};
use serde::{Deserialize, Serialize};
use std::sync::Arc;
use tokio::sync::RwLock;
use uuid::Uuid;

use crate::approval::RiskTier;

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct AuditEvent {
    pub id: String,
    pub session_id: String,
    pub tool_name: String,
    pub risk_tier: RiskTier,
    pub description: String,
    pub approved: bool,
    pub success: bool,
    pub execution_duration_ms: u64,
    pub timestamp: DateTime<Utc>,
}

#[derive(Clone, Default)]
pub struct AuditLogger {
    events: Arc<RwLock<Vec<AuditEvent>>>,
}

impl AuditLogger {
    pub fn new() -> Self {
        Self {
            events: Arc::new(RwLock::new(Vec::new())),
        }
    }

    pub async fn record(
        &self,
        session_id: &str,
        tool_name: &str,
        risk_tier: RiskTier,
        description: &str,
        approved: bool,
        success: bool,
        duration_ms: u64,
    ) -> AuditEvent {
        let event = AuditEvent {
            id: Uuid::new_v4().to_string(),
            session_id: session_id.to_string(),
            tool_name: tool_name.to_string(),
            risk_tier,
            description: description.to_string(),
            approved,
            success,
            execution_duration_ms: duration_ms,
            timestamp: Utc::now(),
        };

        let mut events = self.events.write().await;
        events.push(event.clone());
        event
    }

    pub async fn get_history(&self, session_id: Option<&str>) -> Vec<AuditEvent> {
        let events = self.events.read().await;
        if let Some(sid) = session_id {
            events.iter().filter(|e| e.session_id == sid).cloned().collect()
        } else {
            events.clone()
        }
    }
}

pub mod approval;
pub mod audit;
pub mod policy;

pub use approval::{ApprovalDecision, ApprovalEngine, ApprovalRequest, RiskTier};
pub use audit::{AuditEvent, AuditLogger};
pub use policy::{ExecutionMode, SecurityPolicy};

use serde::{Deserialize, Serialize};

#[derive(Debug, Clone, Serialize, Deserialize, PartialEq, Eq)]
#[serde(rename_all = "snake_case")]
pub enum ExecutionMode {
    Autonomous, // Auto-approves Tier 0 and Tier 1, asks Tier 2
    Supervised, // Asks for Tier 1 and Tier 2
    Locked,     // Tier 0 only, all mutating calls rejected
}

#[derive(Debug, Clone, Serialize, Deserialize)]
pub struct SecurityPolicy {
    pub mode: ExecutionMode,
    pub allowed_directories: Vec<String>,
    pub forbidden_commands: Vec<String>,
    pub max_execution_time_secs: u64,
}

impl Default for SecurityPolicy {
    fn default() -> Self {
        Self {
            mode: ExecutionMode::Autonomous,
            allowed_directories: Vec::new(),
            forbidden_commands: vec![
                "rm -rf /".to_string(),
                "rm -rf ~".to_string(),
                ":(){ :|:& };:".to_string(), // fork bomb
                "mkfs".to_string(),
                "dd if=/dev/zero".to_string(),
            ],
            max_execution_time_secs: 300,
        }
    }
}

impl SecurityPolicy {
    pub fn is_command_forbidden(&self, command: &str) -> bool {
        let cmd_lower = command.to_lowercase();
        self.forbidden_commands.iter().any(|f| cmd_lower.contains(&f.to_lowercase()))
    }
}

