        "fs_write"
    }
    fn description(&self) -> &str {
        "Write content to a file, creating parent directories if needed"
    }
    fn parameters_schema(&self) -> Value {
        json!({
            "type": "object",
            "properties": {
                "path": { "type": "string", "description": "Target file path" },
